script:
/* italic serif fallback until the builder font loader carries ital */
@import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,wght@1,400;1,600&display=swap');

html { scroll-behavior: smooth; }
::selection { background: #211E18; color: #F5F2EA; }

html.cn-js .cn-rise { opacity: 0; transform: translateY(18px); }
html.cn-js .cn-rise.cn-in {
  opacity: 1; transform: none;
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}
html.cn-js .cn-d1.cn-in { transition-delay: 0.14s; }
html.cn-js .cn-d2.cn-in { transition-delay: 0.28s; }

html.cn-js .cn-rule { transform: scaleX(0); transform-origin: left; }
html.cn-js .cn-rule.cn-in { transform: scaleX(1);
  transition: transform 1.1s cubic-bezier(0.22, 1, 0.36, 1); }

.cn-grow { flex-grow: 1; flex-shrink: 1; min-width: 0; }

.cn-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1px;
  transition: background-size 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}
.cn-ul:hover { background-size: 100% 1px; }

.cn-btn { transition: background-color 0.3s ease, color 0.3s ease; }
.cn-btn:hover { background-color: #7A2C25; }
.cn-btn-o { transition: background-color 0.3s ease, color 0.3s ease,
  border-color 0.3s ease; }
.cn-btn-o:hover { background-color: #211E18; border-color: #211E18;
  color: #F5F2EA; }

.cn-area { transition: background-color 0.35s ease, padding-left 0.35s
  cubic-bezier(0.22, 1, 0.36, 1); }
.cn-area:hover { background-color: #FCFAF4; padding-left: 26px; }
.cn-area .cn-arrow { opacity: 0; transform: translateX(-6px);
  transition: opacity 0.3s ease, transform 0.3s ease; }
.cn-area:hover .cn-arrow { opacity: 1; transform: none; }

.cn-panel { transition: border-color 0.35s ease, transform 0.35s
  cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.35s ease; }
.cn-panel:hover { border-color: #211E18; transform: translateY(-4px);
  box-shadow: 0 16px 36px rgba(33, 30, 24, 0.08); }

.cn-frame img { transition: filter 0.6s ease, transform 0.6s
  cubic-bezier(0.22, 1, 0.36, 1); }
.cn-frame:hover img { filter: grayscale(0) contrast(1);
  transform: scale(1.025); }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}
